import { Spiral, type SpiralProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

interface ShaderSpiralProps extends Omit<SpiralProps, "frame" | "ref"> {}

function ShaderSpiralBase({
  speed = 1,
  colorBack = "#12121a",
  colorFront = "#52527a",
  density = 1,
  strokeWidth = 0.5,
  softness = 0.2,
  className,
  ...rest
}: ShaderSpiralProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("shader-spiral"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <Spiral
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colorBack={colorBack}
        colorFront={colorFront}
        density={density}
        strokeWidth={strokeWidth}
        softness={softness}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  density: {
    type: "number",
    min: 0.2,
    max: 4,
    step: 0.1,
    default: 1,
    description: "Density",
    hiddenFromList: false,
  },
  strokeWidth: {
    type: "number",
    min: 0.05,
    max: 1,
    step: 0.05,
    default: 0.5,
    description: "Stroke",
    hiddenFromList: false,
  },
  softness: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.2,
    description: "Softness",
    hiddenFromList: false,
  },
  colorBack: {
    type: "color",
    default: "#12121a",
    description: "Background",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","density","strokeWidth","softness","colorBack"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  density: 1,
  strokeWidth: 0.5,
  softness: 0.2,
  colorBack: "#12121a",
};

type ShaderSpiralElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderSpiralBase>;

const ShaderSpiralInner = forwardRef<
  HTMLDivElement,
  ShaderSpiralElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderSpiral>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderSpiralBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderSpiralBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderSpiral = Interactive.withSchema({
  Component: ShaderSpiralInner,
  componentName: "<ShaderSpiral>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
